object AppIcons {
    private fun icon(name: String, d: String, mirror: Boolean, big: Boolean): ImageVector {
        val vp = if (big) 960f else 24f
        return ImageVector.Builder(name, 24.dp, 24.dp, vp, vp, autoMirror = mirror).apply {
            group(translationY = if (big) 960f else 0f) {
                addPath(addPathNodes(d), fill = SolidColor(Color.Black))
            }
        }.build()
    }

