    /** The vector for one of the budget-line emoji the app offers; null for anything else. */
    fun forEmoji(e: String): ImageVector? = when (e.removeSuffix("\uFE0F")) {
        "🏠" -> Home; "🤝" -> Handshake; "💝" -> Favorite; "💡" -> Lightbulb; "💳" -> CreditCard
        "🛒" -> ShoppingCart; "🚗" -> DirectionsCar; "☕" -> LocalCafe; "🚑" -> MedicalServices; "💰" -> Savings
        "🍔" -> LunchDining; "👕" -> Checkroom; "💊" -> Medication; "🎓" -> School; "📱" -> Smartphone
        "🎁" -> Redeem; "👶" -> ChildCare; "✈" -> Flight; "🏋" , "🏋️" -> FitnessCenter; "🐾" -> Pets
        "🧾" -> ReceiptLong; "🔧" -> Build; "🎮" -> SportsEsports; "📦" -> InventoryBox
        "💵" -> Payments; "🚘" -> DirectionsCar; "⛽" -> DirectionsCar; "🌐" -> Language; "📌" -> Event; "🏦" -> AccountBalance; "📩" -> Notifications; "🎯" -> Savings; "🍽" -> LunchDining; "🎉" -> Group; "👥" -> Group
        else -> null
    }
